#!/usr/bin/env node
// Generates the enhanced-links parameter reference fragment for the documentation site.
// Reads the target configuration from le-config.js (Single Source) and merges
// i18n texts from le-i18n-<lang>.json (exported by export-le-i18n.php).
//
// With --lang=<code> (e.g. --lang=de):
//   - structural strings (auto-generated notice, table header) switch to that language
//   - i18n content loads from util/le-i18n-<code>.json
// Without the flag (or --lang=en): EN structural strings, util/le-i18n-en.json.
//
// Output: stdout (fragment, no frontmatter)
// Target: content/{en,de}/includes/linkenhancer/le-link-parameters.md (in wt-modules)
//
// Run:
//   node util/generate-link-params.mjs > .../content/en/includes/linkenhancer/le-link-parameters.md
//   node util/generate-link-params.mjs --lang=de > .../content/de/includes/linkenhancer/le-link-parameters.md
//
// Pre-step (regenerate texts after changing LinkEnhancerUtils.php):
//   php util/export-le-i18n.php > util/le-i18n-en.json
//   php util/export-le-i18n.php --lang=de > util/le-i18n-de.json

import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

import { getLETargetCfg, getLEOptions } from '../resources/js/src/le-config.js';
import { getLErecTypes } from '../resources/js/src/le-xref-parser.js';

const __dirname = dirname(fileURLToPath(import.meta.url));
const langArg = process.argv.find(a => a.startsWith('--lang='));
const lang = langArg ? langArg.slice(7) : 'en';
const i18nPath = join(__dirname, `le-i18n-${lang}.json`);

let i18n = {};
try {
    i18n = JSON.parse(readFileSync(i18nPath, 'utf8'));
} catch {
    process.stderr.write(`WARNING: ${i18nPath} not found — using raw keys\n`);
}

// Structural (non-PO) strings, keyed by language. These live in the script
// because they are NOT in the PO files.
const uiMap = {
    en: {
        auto: '_Auto-generated by `util/generate-link-params.mjs` — do not edit manually._',
        head: '| Key | Name | Syntax | Description |',
    },
    de: {
        auto: '_Automatisch generiert von `util/generate-link-params.mjs` — nicht manuell bearbeiten._',
        head: '| Schlüssel | Name | Syntax | Beschreibung |',
    },
};
const ui = uiMap[lang] ?? uiMap.en;

const options = Object.assign(getLEOptions(), {
    I18N: i18n,
    baseurl: 'https://example.org/tree/main',
    tree: 'main',
    urlmode: 'standard',
});

const cfg = getLETargetCfg(options, getLErecTypes);

const rows = [];

for (const [key, target] of Object.entries(cfg)) {
    const name = target.name
        .replace(/ - \$ID/, '')
        .replace(/%s/, '')
        .replace(/ {2,}/g, ' ')
        .trim();

    if (target.help && target.help.length > 0) {
        for (const h of target.help) {
            const desc = h.n
                .replace(/%s/, '')
                .replace(/ {2,}/g, ' ')
                .trim();
            rows.push({ key, name, syntax: `${key}=${h.e}`, desc });
        }
    } else {
        rows.push({ key, name, syntax: `${key}=ID`, desc: '' });
    }
}

// Deduplicate: if a key has multiple rows, only show name on the first.
const seen = new Set();
const finalRows = rows.map(r => {
    const first = !seen.has(r.key);
    seen.add(r.key);
    return { ...r, name: first ? r.name : '' };
});

// Emit fragment (no frontmatter).
console.log(ui.auto);
console.log('');
console.log(ui.head);
console.log('| --- | --- | --- | --- |');

for (const r of finalRows) {
    const nameCol = r.name.replace(/\|/g, '\\|');
    const descCol = r.desc
        .replace(/<a href="([^"]+)">([^<]+)<\/a>/g, '[$2]($1)')
        .replace(/\|/g, '\\|');
    const syntaxCol = `\`${r.syntax}\``;
    console.log(`| \`${r.key}\` | ${nameCol} | ${syntaxCol} | ${descCol} |`);
}
